import{_ as n,o as r,c as s,a1 as o}from"./chunks/framework.DTPhowZX.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"news/calendar.md","filePath":"news/calendar.md","lastUpdated":1793020529000}'),g={name:"news/calendar.md"};function p(l,t,i,e,a,_){return r(),s("div",null,[...t[0]||(t[0]=[o("<p><strong>🏛️ Ключевые юбилеи 2026 года (Указы Президента РФ)</strong></p><p>В 2026 году на государственном уровне отмечаются следующие значимые юбилеи :</p><ul><li><p><strong>250 лет</strong> со дня основания Государственного академического Большого театра России (Указ № 12 от 17.01.2022).</p></li><li><p><strong>225 лет</strong> со дня рождения <strong>В. И. Даля</strong>, писателя, этнографа, автора «Толкового словаря живого великорусского языка» (Указ № 843 от 08.11.2023).</p></li><li><p><strong>200 лет</strong> со дня рождения <strong>М. Е. Салтыкова-Щедрина</strong>, писателя-сатирика (Указ № 134 от 10.03.2025).</p></li><li><p><strong>80 лет</strong> со дня образования <strong>Калининградской области</strong> (Указ № 135 от 10.03.2025).</p></li></ul><p><strong>📅 Дни воинской славы и памятные даты истории России</strong></p><p>Согласно Федеральному закону «О днях воинской славы и памятных датах России», в 2026 году отмечаются следующие ключевые события :</p><ul><li><p><strong>27 января</strong> — День полного освобождения Ленинграда от фашистской блокады (1944 год).</p></li><li><p><strong>2 февраля</strong> — День разгрома советскими войсками немецко-фашистских войск в Сталинградской битве (1943 год).</p></li><li><p><strong>23 февраля</strong> — День защитника Отечества.</p></li><li><p><strong>18 марта</strong> — День воссоединения Крыма с Россией (с 2014 года, отмечается как памятная дата).</p></li><li><p><strong>9 мая</strong> — День Победы советского народа в Великой Отечественной войне 1941–1945 годов.</p></li><li><p><strong>22 июня</strong> — День памяти и скорби — день начала Великой Отечественной войны (1941 год).</p></li><li><p><strong>28 июля</strong> — День Крещения Руси (памятная дата).</p></li><li><p><strong>9 октября</strong> — День разгрома советскими войсками немецко-фашистских войск в битве за Кавказ (1943 год).</p></li><li><p><strong>4 ноября</strong> — День народного единства.</p></li><li><p><strong>7 ноября</strong> — День проведения военного парада на Красной площади в Москве (1941 год).</p></li><li><p><strong>1 декабря</strong> — День победы русской эскадры под командованием П. С. Нахимова над турецкой эскадрой у мыса Синоп (1853 год).</p></li><li><p><strong>3 декабря</strong> — День Неизвестного Солдата.</p></li><li><p><strong>5 декабря</strong> — День начала контрнаступления советских войск против немецко-фашистских войск в битве под Москвой (1941 год).</p></li><li><p><strong>24 декабря</strong> — День взятия турецкой крепости Измаил русскими войсками под командованием А. В. Суворова (1790 год).</p></li></ul><p><strong>👤 Круглые даты исторических личностей (историки, полководцы, государственные деятели)</strong></p><p>В 2026 году исполняется множество юбилеев со дня рождения выдающихся деятелей, связанных с историей России :</p><ul><li><p><strong>28 января</strong> — <strong>185 лет</strong> со дня рождения <strong>В. О. Ключевского</strong>, выдающегося русского историка.</p></li><li><p><strong>13 февраля</strong> — <strong>220 лет</strong> со дня рождения <strong>В. А. Корнилова</strong>, героя Крымской войны.</p></li><li><p><strong>16 сентября</strong> — <strong>280 лет</strong> со дня рождения <strong>М. И. Кутузова</strong>, великого русского полководца.</p></li><li><p><strong>13 ноября</strong> — <strong>295 лет</strong> со дня рождения <strong>А. В. Суворова</strong>, основоположника русской военной теории.</p></li><li><p><strong>19 ноября</strong> — <strong>315 лет</strong> со дня рождения <strong>М. В. Ломоносова</strong>, учёного-энциклопедиста, историка.</p></li><li><p><strong>25 ноября</strong> — <strong>215 лет</strong> со дня рождения <strong>Н. И. Пирогова</strong>, хирурга, участника обороны Севастополя.</p></li><li><p><strong>12 декабря</strong> — <strong>260 лет</strong> со дня рождения <strong>Н. М. Карамзина</strong>, писателя и историка, автора «Истории государства Российского».</p></li><li><p>Также в 2026 году отмечается <strong>130 лет</strong> со дня рождения маршалов <strong>Г. К. Жукова</strong> и <strong>К. К. Рокоссовского</strong> .</p></li></ul><p><strong>📜 Прочие важные исторические юбилеи</strong></p><ul><li><p><strong>1115 лет</strong> со дня заключения первого договора Руси с Византией (911 год) .</p></li><li><p><strong>805 лет</strong> со дня рождения князя <strong>Александра Невского</strong> (1221 год) .</p></li><li><p><strong>165 лет</strong> со дня отмены крепостного права в России (1861 год) .</p></li><li><p><strong>120 лет</strong> с начала <strong>Столыпинской аграрной реформы</strong> (1906 год) .</p></li><li><p><strong>65 лет</strong> со дня первого полёта человека в космос (Ю. А. Гагарин, 1961 год) .</p></li><li><p><strong>40 лет</strong> со дня аварии на Чернобыльской АЭС (1986 год) .</p></li></ul>",11)])])}const u=n(g,[["render",p]]);export{d as __pageData,u as default};
